SHELL := /bin/bash
.DEFAULT_GOAL := help

VERSION := $(shell tr -d '[:space:]' < VERSION)
IMAGE := igame:v$(VERSION)
COMMIT := $(shell git rev-parse --short=12 HEAD 2>/dev/null || printf unknown)
BUILD_DATE := $(shell date -u '+%Y-%m-%dT%H:%M:%SZ')

.PHONY: help deps fmt lint test test-race test-db docs-pdf guide-shots sdk-build web-build check-offline-bundle build docker-build smoke realmguard-smoke defense-smoke release verify-release check-contract clean

help: ## Show available targets
	@awk 'BEGIN {FS = ":.*## "; printf "igame build targets:\n"} /^[a-zA-Z0-9_-]+:.*## / {printf "  %-18s %s\n", $$1, $$2}' $(MAKEFILE_LIST)

deps: ## Install locked Go and Node dependencies
	go mod download
	npm --prefix sdk/gamehub-js ci
	npm --prefix web ci

fmt: ## Format Go source
	gofmt -w $$(find . -name '*.go' -not -path './web/*' -not -path './sdk/*')

lint: ## Run Go vet and frontend linters
	@unformatted="$$(gofmt -l $$(find cmd internal migrations -name '*.go' -type f))"; \
	  if [[ -n "$$unformatted" ]]; then printf 'Go files need gofmt:\n%s\n' "$$unformatted" >&2; exit 1; fi
	go vet ./cmd/... ./internal/... ./migrations/...
	npm --prefix sdk/gamehub-js run lint
	npm --prefix web run lint

test: ## Run Go, SDK, and frontend tests
	go test ./cmd/... ./internal/... ./migrations/...
	npm --prefix sdk/gamehub-js test
	npm --prefix web test

test-race: ## Run the Go tests under the race detector
	go test -race ./cmd/... ./internal/... ./migrations/...

test-db: ## Run the tests that need PostgreSQL; set DSN=postgres://...
	@if [[ -z "$(DSN)" ]]; then printf 'set DSN to a database these tests may migrate and write to\n' >&2; exit 1; fi
	IGAME_TEST_DSN="$(DSN)" go test ./internal/api/... ./internal/database/... -count=1

docs-pdf: ## Rebuild the manual PDFs from their Markdown sources
	bash ./scripts/build-docs-pdf.sh

guide-shots: ## Recapture docs/assets/guide from a disposable service; see the script header
	bash ./scripts/capture-guide-screenshots.sh

sdk-build: ## Build the JavaScript Game SDK
	npm --prefix sdk/gamehub-js run build

web-build: sdk-build ## Build the React portal
	npm --prefix web run build
	bash ./scripts/check-offline-bundle.sh

check-offline-bundle: web-build ## Verify Phaser and RealmGuard are bundled without remote assets

build: web-build ## Build the versioned Go binary
	bash ./scripts/build-local.sh "$(VERSION)" "$(COMMIT)" "$(BUILD_DATE)"

check-contract: ## Check version and runtime environment contracts
	bash ./scripts/check-release-contract.sh

docker-build: check-contract ## Build the single offline image
	docker build \
	  --platform linux/amd64 \
	  --build-arg VERSION=$(VERSION) \
	  --build-arg COMMIT=$(COMMIT) \
	  --build-arg BUILD_DATE=$(BUILD_DATE) \
	  --tag $(IMAGE) .

smoke: ## Smoke-test a running service; override URL=...
	bash ./scripts/smoke-test.sh "$(or $(URL),http://127.0.0.1:8080)"

realmguard-smoke: ## Test RealmGuard on a disposable fresh service; set ADMIN and PASSWORD
	bash ./scripts/smoke-realmguard.sh "$(or $(URL),http://127.0.0.1:8080)" "$(ADMIN)" "$(PASSWORD)"

defense-smoke: ## Test all Defense Series contracts; set ADMIN and PASSWORD
	bash ./scripts/smoke-defense-series.sh "$(or $(URL),http://127.0.0.1:8080)" "$(ADMIN)" "$(PASSWORD)"

release: check-contract ## Build the single release asset plus local SBOM/checksum evidence
	bash ./scripts/release.sh

verify-release: ## Verify the release archive; override ARCHIVE=...
	bash ./scripts/verify-release.sh "$(or $(ARCHIVE),dist/igame-v$(VERSION).tar.gz)"

clean: ## Remove generated local build output
	rm -rf bin dist web/dist sdk/gamehub-js/dist
// Package config loads igame's deliberately small bootstrap configuration.
// All mutable service configuration is stored in PostgreSQL.
package config

import (
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"strings"
	"unicode/utf8"
)

const (
	EnvPostgresDSN        = "POSTGRES_DSN"
	EnvBootstrapAdmin     = "BOOTSTRAP_ADMIN"
	EnvBootstrapAdminPass = "BOOTSTRAP_ADMIN_PASSWORD"
	EnvEncryptionKey      = "ENCRYPTION_KEY"
)

type Config struct {
	PostgresDSN       string
	BootstrapAdmin    string
	BootstrapPassword string
	EncryptionKey     []byte
}

func Load() (Config, error) {
	c := Config{
		PostgresDSN:       strings.TrimSpace(os.Getenv(EnvPostgresDSN)),
		BootstrapAdmin:    strings.TrimSpace(os.Getenv(EnvBootstrapAdmin)),
		BootstrapPassword: os.Getenv(EnvBootstrapAdminPass),
	}
	var missing []string
	if c.PostgresDSN == "" {
		missing = append(missing, EnvPostgresDSN)
	}
	if c.BootstrapAdmin == "" {
		missing = append(missing, EnvBootstrapAdmin)
	}
	if c.BootstrapPassword == "" {
		missing = append(missing, EnvBootstrapAdminPass)
	}
	keyText := strings.TrimSpace(os.Getenv(EnvEncryptionKey))
	if keyText == "" {
		missing = append(missing, EnvEncryptionKey)
	}
	if len(missing) != 0 {
		return Config{}, fmt.Errorf("missing required environment variables: %s", strings.Join(missing, ", "))
	}
	if utf8.RuneCountInString(c.BootstrapPassword) < 12 {
		return Config{}, fmt.Errorf("%s must be at least 12 characters", EnvBootstrapAdminPass)
	}
	key, err := ParseEncryptionKey(keyText)
	if err != nil {
		return Config{}, fmt.Errorf("%s: %w", EnvEncryptionKey, err)
	}
	c.EncryptionKey = key
	return c, nil
}

func ParseEncryptionKey(value string) ([]byte, error) {
	if strings.HasPrefix(value, "base64:") {
		b, err := base64.StdEncoding.DecodeString(strings.TrimPrefix(value, "base64:"))
		if err != nil {
			return nil, errors.New("invalid base64 value")
		}
		return validateKey(b)
	}
	if strings.HasPrefix(value, "hex:") {
		b, err := hex.DecodeString(strings.TrimPrefix(value, "hex:"))
		if err != nil {
			return nil, errors.New("invalid hex value")
		}
		return validateKey(b)
	}
	// A plain 32-byte value keeps first-time offline installation simple.
	return validateKey([]byte(value))
}

func validateKey(key []byte) ([]byte, error) {
	if len(key) != 32 {
		return nil, fmt.Errorf("must decode to exactly 32 bytes, got %d", len(key))
	}
	return append([]byte(nil), key...), nil
}
package config

import "testing"

func TestParseEncryptionKey(t *testing.T) {
	for _, in := range []string{
		"12345678901234567890123456789012",
		"hex:3132333435363738393031323334353637383930313233343536373839303132",
		"base64:MTIzNDU2Nzg5MDEyMzQ1Njc4OTAxMjM0NTY3ODkwMTI=",
	} {
		got, err := ParseEncryptionKey(in)
		if err != nil || len(got) != 32 {
			t.Fatalf("ParseEncryptionKey(%q) = %d, %v", in, len(got), err)
		}
	}
	if _, err := ParseEncryptionKey("short"); err == nil {
		t.Fatal("expected short key error")
	}
}

func TestLoadRejectsWeakBootstrapPassword(t *testing.T) {
	t.Setenv(EnvPostgresDSN, "postgres://example/igame")
	t.Setenv(EnvBootstrapAdmin, "admin")
	t.Setenv(EnvBootstrapAdminPass, "too-short")
	t.Setenv(EnvEncryptionKey, "12345678901234567890123456789012")
	if _, err := Load(); err == nil {
		t.Fatal("expected a weak bootstrap password error")
	}

	t.Setenv(EnvBootstrapAdminPass, "long-enough-12")
	if _, err := Load(); err != nil {
		t.Fatalf("expected a valid bootstrap password, got %v", err)
	}
}

